183	            for (int i = 0; i < animals.size(); i++){
184	                if ((animals.get(i) instanceof Ant || (animals.get(i) instanceof Rat))) {
185	                    randomRatsAnts.add(animals.get(i));
186	                }
187	            }
188	            Collections.shuffle(randomRatsAnts);
189	            for (int i = 0; i < ((randomRatsAnts.size())/5); i++){
190	                animals.get(i).setDead();
191	            }
192	        }
193	        else if (weather.equals("drought")){
194	            resetWeather();
195	            List<Plant> randomPlants = new ArrayList<>();
196	            for (int i = 0; i < plants.size(); i++){
197	                randomPlants.add(plants.get(i));
198	            }
199	            Collections.shuffle(randomPlants);
200	            for (int i = 0; i < ((plants.size())/5); i++){
201	                plants.remove(plants.get(i));
202	            }
203	        }
204	        else if (weather.equals("fog")) {
205	            resetWeather();
206	            for (int i = 0; i < animals.size(); i++) {
207	                animals.get(i).setFog();
208	            }
209	        }
210	
211	        // Provide space for newborn animals.
212	        List<Animal> newAnimals = new ArrayList<>();        
213	        // Let all ants act.
214	        for(Iterator<Animal> it = animals.iterator(); it.hasNext(); ) {
215	            Animal animal = it.next();
216	            animal.act(newAnimals,time);
217	            if(! animal.isAlive()) {
218	                it.remove();
219	            }
220	        }
221	
222	        //provide space for new created plants
223	        List<Plant> newPlants = new ArrayList<>();
224	        for(Iterator<Plant> it = plants.iterator(); it.hasNext(); ) {
225	            Plant plant = it.next();
226	            plant.act(newPlants);
227	            if(! plant.isAlive()) {
228	                it.remove();
229	            }
230	        }
231	
232	               
233	        // Add the newly born animals and plants to the main lists.
234	        animals.addAll(newAnimals);
235	        plants.addAll(newPlants);
236	
237	        view.showStatus(step, field, time, weather);
238	    }
